// Normalizes the signup no matter how it arrived: the Webhook node wraps the
// POSTed JSON in `body`, while the manual Sample signup item is already flat.
const item = $input.first().json;
const src = item && typeof item.body === 'object' && item.body !== null ? item.body : item;

// Length caps keep malformed or hostile input from wrecking the layout.
const clean = (v, max) => String(v == null ? '' : v).replace(/\s+/g, ' ').trim().slice(0, max);
const firstName = clean(src.firstName, 40);
const plan = clean(src.plan, 48);
const company = clean(src.company, 90);
const email = clean(src.email, 120);

if (!firstName) {
  throw new Error('The signup needs at least a firstName. Expected POST body: { "firstName": "Maya", "plan": "Pro trial", "company": "Northwind Labs", "email": "optional — only used when sendEmail is true" }');
}

return [{ json: { firstName, plan, company, email, receivedVia: (item && typeof item.body === 'object' && item.body !== null) ? 'webhook' : 'manual-test' } }];

// Assembles the Zvid project JSON: a branded welcome scene, three "what to do
// first" cards, and a CTA scene — personalised with the signup's firstName,
// plan and company. Long names get a smaller headline automatically, and every
// user-provided string is HTML-escaped before it reaches the renderer.
function buildProject(config, data) {
  const cfg = config || {};
  const esc = (s) =>
    String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({
      '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
    }[c]));

  const hexToRgba = (hex, alpha) => {
    const m = /^#?([0-9a-f]{6})$/i.exec(String(hex || '').trim());
    if (!m) return `rgba(108,140,255,${alpha})`;
    const n = parseInt(m[1], 16);
    return `rgba(${(n >> 16) & 255},${(n >> 8) & 255},${n & 255},${alpha})`;
  };

  // ---- signup data ---------------------------------------------------------
  const firstName = String((data && data.firstName) || '').trim() || 'there';
  const plan = String((data && data.plan) || '').trim();
  const company = String((data && data.company) || '').trim();

  // Config knobs may embed {firstName} / {plan} / {company} / {brand} tokens.
  // Substitute raw values first, escape the whole string after.
  const brand = String(cfg.brandName || 'Your product').trim();
  const tok = (s) =>
    esc(
      String(s == null ? '' : s)
        .replace(/\{firstName\}/g, firstName)
        .replace(/\{plan\}/g, plan)
        .replace(/\{company\}/g, company)
        .replace(/\{brand\}/g, brand)
    );

  const bg = cfg.brandBackground || '#0B1020';
  const glow = cfg.brandGlow || '#1B2450';
  const accent = cfg.brandAccent || '#6C8CFF';
  const font = cfg.font || 'Outfit';
  const soft = '#AEB8D6'; // secondary text on the dark background
  const faint = 'rgba(255,255,255,0.5)';

  // ---- adaptive type sizes (long names must not clip) ----------------------
  const n = firstName.length;
  const hSize = n <= 9 ? 124 : n <= 14 ? 106 : n <= 20 ? 92 : 78;
  const cSize = n <= 9 ? 92 : n <= 14 ? 82 : n <= 20 ? 72 : 62;

  // ---- copy ----------------------------------------------------------------
  const planChip = plan ? plan.toUpperCase() : 'WELCOME ABOARD';
  const welcomeSub = company
    ? `Your ${brand} workspace for ${company} is ready. ${String(cfg.welcomeSub || "Here's how to make week one count.")}`
    : `Your ${brand} workspace is ready. ${String(cfg.welcomeSub || "Here's how to make week one count.")}`;
  const cards = (Array.isArray(cfg.cards) ? cfg.cards : []).slice(0, 3);
  while (cards.length < 3) cards.push({ title: 'Explore', detail: 'Take a look around your new workspace.' });
  const ctaHeadline = cfg.ctaHeadline || "You're all set, {firstName}.";
  const ctaText = cfg.ctaText || 'Open your workspace';
  const ctaUrl = String(cfg.ctaUrl || '').trim();
  const supportNote = cfg.supportNote || '';
  const stepsFootnote = cfg.stepsFootnote || 'It all takes about two minutes, {firstName}.';

  // ---- brand lockup (top-left of the welcome scene) ------------------------
  const brandLockup = [];
  if (String(cfg.brandLogoUrl || '').trim()) {
    brandLockup.push({
      type: 'IMAGE', src: String(cfg.brandLogoUrl).trim(),
      x: 100, y: 84, width: 72, height: 72, resize: 'contain', anchor: 'top-left',
      track: 2, enterBegin: 0, exitEnd: 4.6,
    });
    brandLockup.push({
      type: 'TEXT', x: 196, y: 84, anchor: 'top-left', track: 3,
      enterBegin: 0, exitEnd: 4.6, style: { fontFamily: font, color: '#FFFFFF' },
      html: `<div style='line-height:72px; font-size:36px; font-weight:800; letter-spacing:2px; color:#FFFFFF;'>${esc(brand)}</div>`,
    });
  } else {
    const monogram = esc((brand.replace(/[^\p{L}\p{N}]/gu, '')[0] || 'Z').toUpperCase());
    brandLockup.push({
      type: 'TEXT', x: 100, y: 84, anchor: 'top-left', track: 2,
      enterBegin: 0, exitEnd: 4.6, style: { fontFamily: font, color: '#FFFFFF' },
      html: `<div style='display:flex; align-items:center; gap:22px;'><div style='width:72px; height:72px; border-radius:20px; background:${accent}; color:${bg}; font-size:40px; font-weight:800; display:flex; align-items:center; justify-content:center;'>${monogram}</div><div style='font-size:36px; font-weight:800; letter-spacing:2px; color:#FFFFFF;'>${esc(brand)}</div></div>`,
    });
  }

  // ---- scene 1: welcome ----------------------------------------------------
  const welcomeSvg = `<svg width='1920' height='1080' viewBox='0 0 1920 1080' xmlns='http://www.w3.org/2000/svg'><defs><radialGradient id='wvBg' cx='0.5' cy='0.36' r='1'><stop offset='0' stop-color='${glow}'/><stop offset='1' stop-color='${bg}'/></radialGradient></defs><rect width='1920' height='1080' fill='url(#wvBg)'/><circle cx='1730' cy='140' r='260' fill='${hexToRgba(accent, 0.1)}'/><circle cx='180' cy='960' r='210' fill='${hexToRgba(accent, 0.07)}'/><rect x='40' y='40' width='1840' height='1000' rx='40' fill='none' stroke='${hexToRgba(accent, 0.35)}' stroke-width='1.5'/></svg>`;

  const welcome = {
    id: 'welcome',
    duration: 4.6,
    backgroundColor: bg,
    transition: 'smoothleft',
    transitionId: 'steps',
    transitionDuration: 0.55,
    visuals: [
      { type: 'SVG', width: 1920, height: 1080, track: 0, enterBegin: 0, exitEnd: 4.6, svg: welcomeSvg },
      ...brandLockup,
      {
        type: 'TEXT', x: 960, y: 300, anchor: 'top-center', track: 4,
        enterBegin: 0.2, enterEnd: 0.6, enterAnimation: 'fade', exitEnd: 4.6,
        style: { fontFamily: font, color: accent },
        html: `<div style='display:inline-block; border:1.5px solid ${hexToRgba(accent, 0.6)}; border-radius:999px; padding:14px 36px; color:${accent}; font-size:26px; font-weight:700; letter-spacing:5px;'>${esc(planChip)}</div>`,
      },
      {
        type: 'TEXT', x: 960, y: 405, width: 1640, anchor: 'top-center', track: 5,
        enterBegin: 0.45, enterEnd: 0.95, enterAnimation: 'smoothup', exitEnd: 4.6,
        style: { fontFamily: font, color: '#FFFFFF' },
        html: `<div style='text-align:center; color:#FFFFFF; font-size:${hSize}px; line-height:1.06; font-weight:800; letter-spacing:-2px;'>Welcome, ${esc(firstName)}.</div><div style='margin-top:30px; text-align:center; color:${soft}; font-size:34px; line-height:1.45; font-weight:400;'>${esc(welcomeSub)}</div>`,
      },
      ...(ctaUrl
        ? [{
            type: 'TEXT', x: 960, y: 952, anchor: 'top-center', track: 6,
            enterBegin: 0.9, enterEnd: 1.3, enterAnimation: 'fade', exitEnd: 4.6,
            style: { fontFamily: font, color: soft },
            html: `<div style='color:${faint}; font-size:23px; font-weight:600; letter-spacing:4px;'>${esc(ctaUrl).toUpperCase()}</div>`,
          }]
        : []),
    ],
  };

  // ---- scene 2: what to do first (3 cards) ---------------------------------
  const stepsSvg = `<svg width='1920' height='1080' viewBox='0 0 1920 1080' xmlns='http://www.w3.org/2000/svg'><defs><radialGradient id='wvSt' cx='0.32' cy='0.22' r='1.15'><stop offset='0' stop-color='${glow}'/><stop offset='1' stop-color='${bg}'/></radialGradient></defs><rect width='1920' height='1080' fill='url(#wvSt)'/><rect x='40' y='40' width='1840' height='1000' rx='40' fill='none' stroke='${hexToRgba(accent, 0.35)}' stroke-width='1.5'/></svg>`;

  const cardX = [165, 710, 1255];
  const cardVisuals = cards.map((card, i) => ({
    type: 'TEXT', x: cardX[i], y: 300, width: 520, anchor: 'top-left', track: 3 + i,
    enterBegin: 0.35 + i * 0.3, enterEnd: 0.85 + i * 0.3, enterAnimation: 'smoothup', exitEnd: 6.4,
    style: { fontFamily: font, color: '#FFFFFF' },
    html: `<div style='box-sizing:border-box; width:500px; height:560px; background:rgba(255,255,255,0.04); border:1.5px solid ${hexToRgba(accent, 0.4)}; border-radius:36px; padding:44px;'><div style='width:84px; height:84px; border-radius:999px; background:${hexToRgba(accent, 0.14)}; border:2px solid ${accent}; color:${accent}; font-size:40px; font-weight:800; display:flex; align-items:center; justify-content:center;'>${i + 1}</div><div style='margin-top:36px; color:#FFFFFF; font-size:40px; line-height:1.12; font-weight:800; letter-spacing:-1px;'>${tok(card.title)}</div><div style='margin-top:18px; color:${soft}; font-size:26px; line-height:1.5; font-weight:400;'>${tok(card.detail)}</div></div>`,
  }));

  const steps = {
    id: 'steps',
    duration: 6.4,
    backgroundColor: bg,
    transition: 'smoothleft',
    transitionId: 'cta',
    transitionDuration: 0.5,
    visuals: [
      { type: 'SVG', width: 1920, height: 1080, track: 0, enterBegin: 0, exitEnd: 6.4, svg: stepsSvg },
      {
        type: 'TEXT', x: 960, y: 108, anchor: 'top-center', track: 1,
        enterBegin: 0.1, enterEnd: 0.5, enterAnimation: 'fade', exitEnd: 6.4,
        style: { fontFamily: font, color: accent },
        html: `<div style='color:${accent}; font-size:25px; font-weight:700; letter-spacing:6px;'>GETTING STARTED &middot; ${esc(brand).toUpperCase()}</div>`,
      },
      {
        type: 'TEXT', x: 960, y: 158, anchor: 'top-center', track: 2,
        enterBegin: 0.2, enterEnd: 0.65, enterAnimation: 'smoothup', exitEnd: 6.4,
        style: { fontFamily: font, color: '#FFFFFF' },
        html: `<div style='color:#FFFFFF; font-size:64px; font-weight:800; letter-spacing:-1px;'>What to do first</div>`,
      },
      ...cardVisuals,
      {
        type: 'TEXT', x: 960, y: 925, width: 1500, anchor: 'top-center', track: 6,
        enterBegin: 1.5, enterEnd: 1.9, enterAnimation: 'fade', exitEnd: 6.4,
        style: { fontFamily: font, color: soft },
        html: `<div style='text-align:center; color:${soft}; font-size:29px; font-weight:500;'>${tok(stepsFootnote)}</div>`,
      },
    ],
  };

  // ---- scene 3: CTA --------------------------------------------------------
  const ctaSvg = `<svg width='1920' height='1080' viewBox='0 0 1920 1080' xmlns='http://www.w3.org/2000/svg'><defs><radialGradient id='wvEnd' cx='0.5' cy='0.38' r='0.95'><stop offset='0' stop-color='${glow}'/><stop offset='1' stop-color='${bg}'/></radialGradient></defs><rect width='1920' height='1080' fill='url(#wvEnd)'/><rect x='40' y='40' width='1840' height='1000' rx='40' fill='none' stroke='${hexToRgba(accent, 0.4)}' stroke-width='1.5'/><circle cx='960' cy='285' r='105' fill='${hexToRgba(accent, 0.12)}' stroke='${hexToRgba(accent, 0.75)}' stroke-width='3'/><path d='M908 285 L946 326 L1016 242' fill='none' stroke='${accent}' stroke-width='13' stroke-linecap='round' stroke-linejoin='round'/></svg>`;

  const cta = {
    id: 'cta',
    duration: 4.6,
    backgroundColor: bg,
    visuals: [
      { type: 'SVG', width: 1920, height: 1080, track: 0, enterBegin: 0, exitEnd: 4.6, svg: ctaSvg },
      {
        type: 'TEXT', x: 960, y: 455, width: 1560, anchor: 'top-center', track: 1,
        enterBegin: 0.3, enterEnd: 0.8, enterAnimation: 'smoothup', exitEnd: 4.6,
        style: { fontFamily: font, color: '#FFFFFF' },
        html: `<div style='text-align:center; color:#FFFFFF; font-size:${cSize}px; line-height:1.06; font-weight:800; letter-spacing:-2px;'>${tok(ctaHeadline)}</div>`,
      },
      {
        type: 'TEXT', x: 960, y: 645, anchor: 'top-center', track: 2,
        enterBegin: 0.75, enterEnd: 1.15, enterAnimation: 'circleopen', exitEnd: 4.6,
        style: { fontFamily: font, color: accent },
        html: `<div style='display:inline-block; background:${accent}; color:${bg}; border-radius:999px; padding:26px 64px; font-size:36px; font-weight:800;'>${esc(ctaText)} &rarr;</div>`,
      },
      {
        type: 'TEXT', x: 960, y: 815, width: 1400, anchor: 'top-center', track: 3,
        enterBegin: 1.15, enterEnd: 1.55, enterAnimation: 'fade', exitEnd: 4.6,
        style: { fontFamily: font, color: soft },
        html: `<div style='text-align:center; color:${soft}; font-size:25px; line-height:1.5; font-weight:500;'>${tok(supportNote)}</div>${ctaUrl ? `<div style='margin-top:22px; text-align:center; color:${faint}; font-size:23px; font-weight:600; letter-spacing:4px;'>${esc(ctaUrl).toUpperCase()}</div>` : ''}`,
      },
    ],
  };

  // ---- assemble ------------------------------------------------------------
  const scenes = [welcome, steps, cta];
  const audios = [];
  const musicUrl = String(cfg.musicUrl || '').trim();
  if (musicUrl) audios.push({ src: musicUrl, volume: Number(cfg.musicVolume ?? 0.15) });

  const payload = {
    name: `welcome-${firstName}${company ? '-' + company : ''}`.toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60) || 'welcome-video',
    resolution: 'full-hd',
    frameRate: Number(cfg.frameRate ?? 30),
    backgroundColor: bg,
    outputFormat: 'mp4',
    scenes,
    ...(audios.length ? { audios } : {}),
  };

  const transitionOverlap = 0.55 + 0.5;
  const totalDuration = Math.round((4.6 + 6.4 + 4.6 - transitionOverlap) * 100) / 100;

  return {
    payload,
    meta: {
      firstName,
      plan,
      company,
      brand,
      totalDuration,
      sceneCount: scenes.length,
      headlineFontPx: hSize,
      hasLogo: Boolean(String(cfg.brandLogoUrl || '').trim()),
      hasMusic: Boolean(musicUrl),
    },
  };
}

const cfg = $('Config').first().json;
const data = $('Signup data').first().json;
const { payload, meta } = buildProject(cfg, data);
return [{ json: { payload, meta } }];

// The free validate endpoint runs the exact pipeline a render submission runs,
// so a failure here is a payload bug — surface the field list instead of a
// generic HTTP error.
const res = $input.first().json;
const status = res.statusCode ?? (res.valid === true ? 200 : 400);
const body = res.body || { ...res, details: res.errors ?? res.details };

if (status !== 200) {
  const details = Array.isArray(body.details)
    ? body.details.map((d) => `  - ${d.field}: ${d.message}`).join('\n')
    : JSON.stringify(body).slice(0, 500);
  throw new Error(`Zvid rejected the project (HTTP ${status}): ${body.message || body.error}\n${details}`);
}

const build = $('Build project JSON').first().json;
return [{
  json: {
    ...build,
    creditsRequired: body.creditsRequired,
    warnings: body.warnings || [],
    schemaVersion: body.schemaVersion,
  },
}];

// The draft save is best-effort (onError: continue) so a hiccup there never
// blocks the response — the render itself does not need the draft.
const cfg = $('Config').first().json;
const d = $('Check validation').first().json;

let editorLink = null;
let draftId = null;
try {
  const project = $('Save draft to editor').first().json.project;
  if (project && project.id) {
    draftId = project.id;
    editorLink = `${String(cfg.editorUrl || 'https://editor.zvid.io').replace(/\/+$/, '')}/?project=${project.id}`;
  }
} catch (e) { /* draft step failed — carry on without a link */ }

return [{ json: { ...d, editorLink, draftId } }];

// Dry run: validated, quoted and saved as a free draft — no credits spent.
const d = $input.first().json;
const meta = d.meta || {};
return [{
  json: {
    dryRun: true,
    videoUrl: null,
    editorLink: d.editorLink,
    draftId: d.draftId,
    creditsRequired: d.creditsRequired,
    videoSeconds: meta.totalDuration,
    firstName: meta.firstName,
    plan: meta.plan,
    company: meta.company,
    warnings: d.warnings,
    nextStep: d.editorLink
      ? 'Open editorLink to watch the draft, then set dryRun to false in Config to render for real.'
      : 'Set dryRun to false in Config to render for real.',
  },
}];

// Fails fast on a failed render and stops the poll loop from running forever.
const cfg = $('Config').first().json;
const job = $input.first().json;

if (job.state === 'failed') {
  throw new Error('Render failed: ' + (job.failedReason || 'no reason given'));
}

const maxPolls = Math.ceil((Number(cfg.timeoutMinutes || 20) * 60) / Number(cfg.pollSeconds || 10));
if ($runIndex + 1 >= maxPolls) {
  throw new Error(`Render did not finish within ${cfg.timeoutMinutes} minutes (job ${job.id}, state ${job.state}).`);
}

return $input.all();

// Final response for a paid render.
const d = $('Editor link').first().json;
const job = $input.first().json;
const url = typeof job.result === 'string' ? job.result : (job.result && job.result.url) || null;
if (!url) {
  throw new Error('Render completed but returned no output URL: ' + JSON.stringify(job).slice(0, 300));
}
return [{
  json: {
    dryRun: false,
    videoUrl: url,
    editorLink: d.editorLink,
    draftId: d.draftId,
    creditsCharged: d.creditsRequired,
    jobId: job.id,
    videoSeconds: (d.meta || {}).totalDuration,
    firstName: (d.meta || {}).firstName,
  },
}];
